import heapq
from itertools import count

def top_k(nums, k):
    heap = []                                 # min-heap: the k largest so far
    for x in nums:
        heapq.heappush(heap, x)
        if len(heap) > k:
            heapq.heappop(heap)               # evict the smallest candidate
    return sorted(heap, reverse=True)         # heap[0] is the k-th largest

def merge_k(lists):
    heap = [(lst[0], i, 0) for i, lst in enumerate(lists) if lst]
    heapq.heapify(heap)                       # O(k)
    out = []
    while heap:
        val, i, j = heapq.heappop(heap)       # i breaks ties before payloads
        out.append(val)
        if j + 1 < len(lists[i]):
            heapq.heappush(heap, (lists[i][j + 1], i, j + 1))
    return out

class TaskQueue:
    def __init__(self):
        self.heap, self.seq = [], count()     # seq: FIFO among equal priorities
    def push(self, priority, task):
        heapq.heappush(self.heap, (priority, next(self.seq), task))
    def pop(self):
        return heapq.heappop(self.heap)[2]    # lowest priority number first
